t.script:
setTimeout(function(){
    var t = document.querySelector('.toast.show');
    if(t) t.classList.remove('show');
}, 5000);

setTimeout(function(){
    var t = document.querySelector('.toast.show');
    if(t) t.classList.remove('show');
}, 5000);

document.addEventListener('DOMContentLoaded', function() {
    const cards = document.querySelectorAll('.ess-kanban-card');
    const columns = document.querySelectorAll('.ess-kanban-cards-container');
    let draggedCard = null;

    cards.forEach(card => {
        card.addEventListener('dragstart', function(e) {
            draggedCard = this;
            setTimeout(() => this.style.opacity = '0.5', 0);
        });

        card.addEventListener('dragend', function() {
            draggedCard.style.opacity = '1';
            draggedCard = null;
        });
    });

    columns.forEach(column => {
        column.addEventListener('dragover', function(e) {
            e.preventDefault();
            this.style.backgroundColor = 'rgba(124,58,237,0.05)';
        });

        column.addEventListener('dragleave', function() {
            this.style.backgroundColor = '';
        });

        column.addEventListener('drop', function(e) {
            e.preventDefault();
            this.style.backgroundColor = '';
            if (draggedCard) {
                this.appendChild(draggedCard);

                // Update backend
                const taskId = draggedCard.getAttribute('data-task-id');
                const stageId = this.parentElement.getAttribute('data-stage-id');

                const formData = new FormData();
                formData.append('task_id', taskId);
                formData.append('stage_id', stageId);
                formData.append('csrf_token', odoo.csrf_token || document.querySelector('input[name="csrf_token"]').value);

                fetch('/my/tasks/update_stage', {
                    method: 'POST',
                    body: formData
                }).then(response => response.json())
                  .then(data => {
                      if(!data.success) {
                          console.error('Error updating stage:', data.error);
                          // Optionally reload or show toast
                      }
                  }).catch(err => console.error(err));

                // Update counters
                document.querySelectorAll('.ess-kanban-col').forEach(col => {
                    const count = col.querySelectorAll('.ess-kanban-card').length;
                    col.querySelector('.ess-kanban-col-header .badge').textContent = count;
                });
            }
        });
    });
});

div.script:
document.addEventListener('DOMContentLoaded', function() {
    const stageBtns = document.querySelectorAll('.ess-stage-btn');
    stageBtns.forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.preventDefault();

            if (this.classList.contains('active')) return;

            const taskId = this.getAttribute('data-task-id');
            const stageId = this.getAttribute('data-stage-id');

            // Visual update
            stageBtns.forEach(b => b.classList.remove('active'));
            this.classList.add('active');

            const formData = new FormData();
            formData.append('task_id', taskId);
            formData.append('stage_id', stageId);
            formData.append('csrf_token', odoo.csrf_token || document.querySelector('input[name="csrf_token"]').value);

            fetch('/my/tasks/update_stage', {
                method: 'POST',
                body: formData
            }).then(response => response.json())
              .then(data => {
                  if(!data.success) {
                      console.error('Error updating stage:', data.error);
                      alert("Failed to update stage. You may not have permission.");
                      window.location.reload();
                  }
              }).catch(err => {
                  console.error(err);
                  window.location.reload();
              });
        });
    });
});
